// HasCandidates applies the HasEdge predicate on the "candidates" edge.
func HasCandidates() predicate.XInboundMessage {
	return predicate.XInboundMessage(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.O2M, false, CandidatesTable, CandidatesColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasCandidatesWith applies the HasEdge predicate on the "candidates" edge with a given conditions (other predicates).
func HasCandidatesWith(preds ...predicate.XImportCandidate) predicate.XInboundMessage {
	return predicate.XInboundMessage(func(s *sql.Selector) {
		step := newCandidatesStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.XInboundMessage) predicate.XInboundMessage {
	return predicate.XInboundMessage(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.XInboundMessage) predicate.XInboundMessage {
	return predicate.XInboundMessage(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.XInboundMessage) predicate.XInboundMessage {
	return predicate.XInboundMessage(sql.NotPredicates(p))
}
